INSERT IGNORE INTO `user_tenant` (`user_id`, `tenant_id`, `is_tenant_admin`, `created_by`)
SELECT 1, 1, 1, 'system'
WHERE EXISTS (SELECT 1 FROM `user` WHERE id = 1);

